create table if not exists public.clientes_financeiro (id uuid primary key default gen_random_uuid(),nome text not null,nome_fantasia text,cnpj_cpf text,inscricao_estadual text,inscricao_municipal text,email text,telefone text,cep text,logradouro text,numero text,complemento text,bairro text,cidade text,uf text,origem text not null default 'MANUAL' check (origem in ('OMIE','M_LAB','MANUAL')),id_omie text,usa_minaslab boolean not null default false,usa_mlab boolean not null default false,ativo boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists clientes_financeiro_documento_uq on public.clientes_financeiro ((regexp_replace(cnpj_cpf,'[^0-9]','','g'))) where cnpj_cpf is not null and regexp_replace(cnpj_cpf,'[^0-9]','','g') <> '';
create unique index if not exists clientes_financeiro_omie_uq on public.clientes_financeiro (id_omie) where id_omie is not null;
create index if not exists clientes_financeiro_nome_idx on public.clientes_financeiro (lower(nome)); revoke all on public.clientes_financeiro from anon, authenticated;
insert into public.clientes_financeiro (nome,nome_fantasia,cnpj_cpf,cidade,uf,origem,id_omie,usa_minaslab,usa_mlab,ativo) select coalesce(nullif(trim(registro->>'nome'),''),nullif(trim(registro->>'fantasia'),''),'CLIENTE SEM NOME'),nullif(trim(registro->>'fantasia'),''),nullif(trim(registro->>'doc'),''),nullif(trim(regexp_replace(coalesce(registro->>'cidade',''),'\s*\([A-Z]{2}\)\s*$','')),''),nullif(trim(registro->>'uf'),''),'OMIE',nullif(trim(registro->>'omieId'),''),true,false,not coalesce((registro->>'inativo')::boolean,false) from public.ml_registros where colecao='fin_clientes' and apagado=false on conflict do nothing;
alter table public.recebimentos add column if not exists cliente_id uuid references public.clientes_financeiro(id); alter table public.notas_fiscais add column if not exists cliente_id uuid references public.clientes_financeiro(id); create index if not exists recebimentos_cliente_id_idx on public.recebimentos(cliente_id); create index if not exists notas_fiscais_cliente_id_idx on public.notas_fiscais(cliente_id);